-- ─────────────────────────────────────────────────────────────────────────────
-- Integrity rules enforced by the database itself (MySQL ≥ 8.0.16 / MariaDB ≥ 10.2).
-- Stock columns are already UNSIGNED (never negative). Category self-parenting and
-- cycles are prevented in src/services/categoryService.js (MySQL forbids CHECKs on
-- columns with cascading foreign-key actions).
-- ─────────────────────────────────────────────────────────────────────────────
ALTER TABLE `Product`
    ADD CONSTRAINT `Product_price_check` CHECK (`price` >= 0),
    ADD CONSTRAINT `Product_salePrice_check` CHECK (`salePrice` IS NULL OR (`salePrice` >= 0 AND `salePrice` < `price`));

ALTER TABLE `ProductVariant`
    ADD CONSTRAINT `ProductVariant_priceOverride_check` CHECK (`priceOverride` IS NULL OR `priceOverride` >= 0),
    ADD CONSTRAINT `ProductVariant_colorHex_check` CHECK (`colorHex` IS NULL OR `colorHex` REGEXP '^#[0-9A-Fa-f]{6}$');

ALTER TABLE `CartItem` ADD CONSTRAINT `CartItem_quantity_check` CHECK (`quantity` > 0);

ALTER TABLE `SavedItem` ADD CONSTRAINT `SavedItem_quantity_check` CHECK (`quantity` > 0);

ALTER TABLE `Order`
    ADD CONSTRAINT `Order_amounts_check` CHECK (`subtotal` >= 0 AND `discount` >= 0 AND `deliveryFee` >= 0 AND `total` >= 0);

ALTER TABLE `OrderItem`
    ADD CONSTRAINT `OrderItem_amounts_check` CHECK (`quantity` > 0 AND `unitPrice` >= 0 AND `lineTotal` >= 0);

ALTER TABLE `Payment` ADD CONSTRAINT `Payment_amount_check` CHECK (`amount` >= 0);
